class Solution:
    def minFallingPathSum(self, grid: list[list[int]]) -> int:
        n = len(grid)
        first_min, first_col = 0, -1
        second_min = 0
        for row in grid:
            cur_first_min, cur_first_col = float("inf"), -1
            cur_second_min = float("inf")
            for c in range(n):
                prev = second_min if c == first_col else first_min
                val = row[c] + prev
                if val < cur_first_min:
                    cur_second_min = cur_first_min
                    cur_first_min = val
                    cur_first_col = c
                elif val < cur_second_min:
                    cur_second_min = val
            first_min, first_col = cur_first_min, cur_first_col
            second_min = cur_second_min
        return first_min

#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    int minFallingPathSum(std::vector<std::vector<int>>& grid) {
        int n = grid.size();
        int firstMin = 0, firstCol = -1, secondMin = 0;
        for (int r = 0; r < n; ++r) {
            int curFirstMin = INT_MAX, curFirstCol = -1, curSecondMin = INT_MAX;
            for (int c = 0; c < n; ++c) {
                int prev = (c == firstCol) ? secondMin : firstMin;
                int val = grid[r][c] + prev;
                if (val < curFirstMin) {
                    curSecondMin = curFirstMin;
                    curFirstMin = val;
                    curFirstCol = c;
                } else if (val < curSecondMin) {
                    curSecondMin = val;
                }
            }
            firstMin = curFirstMin;
            firstCol = curFirstCol;
            secondMin = curSecondMin;
        }
        return firstMin;
    }
};

